/**
 * Peer MCP connections: `defineConnection({ agent: "<slug>" })` addresses
 * another agent mounted on the same serve host. Discovery keeps the
 * transport symbolic (the target slug); the server resolves it to that
 * agent's MCP endpoint (`/<slug>/v1/mcp`) once mounts and the listen
 * address are known.
 *
 * Local-runtime turns (and host-side `ctx.host.mcp` calls) use the loopback
 * server URL. Cloud-runtime turns run on a VM that cannot reach loopback,
 * so they use the serve `publicUrl` when configured — and omit the peer
 * (with a startup warning) when it is not.
 *
 * A single-agent serve has no peers mounted beside it. Given a peers URL,
 * it resolves every peer there for both runtimes instead of omitting them.
 */
import { isPeerConnectionTransport } from "../types.js";
import { MCP_ENDPOINT_PATH } from "./mcp-endpoint.js";
/** Every peer connection an agent declares, host connections included. */
export function peerConnectionRefs(project) {
    return [...project.agent.connections, ...(project.agent.hostConnections ?? [])].flatMap(({ name, transport }) => isPeerConnectionTransport(transport) ? [{ name, targetSlug: transport.agent }] : []);
}
/**
 * The slug a deployed peer answers to. `agent-sdk deploy` lowercases directory
 * names into slugs, so `{ agent: "Builder" }` names the `builder` deployment.
 */
function peerDeploySlug(targetSlug) {
    return targetSlug.toLowerCase();
}
/** Deploy slugs of every peer an agent declares, deduped and sorted. */
export function peerDeploySlugs(project) {
    const slugs = peerConnectionRefs(project).map(({ targetSlug }) => peerDeploySlug(targetSlug));
    return [...new Set(slugs)].sort();
}
/**
 * Validate every peer MCP connection across `mounts` and return them grouped by
 * the referencing mount's slug. Throws on references to unknown slugs and on
 * self-references (an agent asking itself recurses forever). A single-mode
 * serve mounts no other agents: with a `peersUrl` its peers resolve there,
 * and without one they are omitted with a warning instead of failing boot.
 */
export function collectPeerConnections(mounts, logger, peersUrl) {
    const [solo] = mounts;
    if (mounts.length === 1 && solo?.slug === "") {
        const refs = peerConnectionRefs(solo.project);
        if (refs.length === 0) {
            return new Map();
        }
        if (peersUrl !== undefined) {
            return new Map([["", refs]]);
        }
        logger(`[bdk] warning: agent "${solo.project.name}" has peer MCP connections (${refs.map(({ name }) => name).join(", ")}) but --mode single mounts no other agents, so they are omitted; peers resolve only in multi-agent serve.`);
        return new Map();
    }
    if (peersUrl !== undefined) {
        throw new Error("--peers-url resolves the peers of a single-agent serve (--mode single); a multi-agent serve resolves them among its mounted agents.");
    }
    const knownSlugs = new Set(mounts.map(({ slug }) => slug));
    const bySlug = new Map();
    for (const { slug, project } of mounts) {
        const refs = peerConnectionRefs(project);
        for (const ref of refs) {
            if (ref.targetSlug === slug) {
                throw new Error(`Agent "${slug}" connection "${ref.name}" references itself (agent: "${ref.targetSlug}"); an agent cannot be its own peer.`);
            }
            if (!knownSlugs.has(ref.targetSlug)) {
                throw new Error(`Agent "${slug}" connection "${ref.name}" references unknown peer agent "${ref.targetSlug}". Mounted agents: ${[...knownSlugs].sort().join(", ")}.`);
            }
        }
        if (refs.length > 0) {
            bySlug.set(slug, refs);
        }
    }
    return bySlug;
}
/**
 * Resolve validated peer refs to concrete MCP URLs once the server is
 * listening. `serverUrl` is the loopback base (`http://127.0.0.1:<port>`);
 * `publicUrl` (when configured) is the externally reachable base used for
 * cloud-runtime turns. When the host requires a bearer token, it is attached
 * so peer calls pass the target agent's auth chain.
 */
export function resolvePeerConnections(args) {
    const serverBase = trimTrailingSlash(args.serverUrl);
    const publicBase = args.publicUrl === undefined ? undefined : trimTrailingSlash(args.publicUrl);
    const headers = args.authToken === undefined ? undefined : { authorization: `Bearer ${args.authToken}` };
    return args.refs.map((ref) => ({
        name: ref.name,
        localUrl: `${serverBase}/${ref.targetSlug}${MCP_ENDPOINT_PATH}`,
        ...(publicBase === undefined
            ? {}
            : { cloudUrl: `${publicBase}/${ref.targetSlug}${MCP_ENDPOINT_PATH}` }),
        ...(headers === undefined ? {} : { headers }),
    }));
}
/**
 * Resolve a single-agent serve's peers against a host that serves each agent
 * at `<peersUrl>/<slug>/v1/mcp`. Local and cloud turns share the URL. The
 * bearer is the Cursor API key bound to this host, expanded each time a
 * client opens, so a key bound after listen still authenticates.
 */
export function resolveHostedPeerConnections(args) {
    const base = trimTrailingSlash(args.peersUrl);
    return args.refs.map((ref) => {
        const url = `${base}/${peerDeploySlug(ref.targetSlug)}${MCP_ENDPOINT_PATH}`;
        return {
            name: ref.name,
            localUrl: url,
            cloudUrl: url,
            headers: { authorization: "Bearer ${CURSOR_API_KEY}" },
        };
    });
}
function trimTrailingSlash(url) {
    return url.endsWith("/") ? url.slice(0, -1) : url;
}
